const vocab={'Commercial wrap':['رپ تبلیغاتی','Habillage commercial','Rotulación comercial'],'Colour change':['تغییر رنگ','Changement de couleur','Cambio de color'],Van:['ون','Fourgon','Furgoneta'],Truck:['کامیون / پیکاپ','Camion / pickup','Camión / pickup'],'Mini Van':['مینی‌ون','Minivan','Minivan'],Trailer:['تریلر','Remorque','Remolque'],SUV:['شاسی‌بلند','VUS','SUV'],Sedan:['سدان','Berline','Sedán'],Other:['سایر','Autre','Otros'],Construction:['ساخت‌وساز','Construction','Construcción'],Electric:['برق','Électricité','Electricidad'],Trading:['تجارت','Commerce','Comercio'],'Wood and Kitchen':['چوب و کابینت','Bois et cuisines','Madera y cocinas'],Plumbing:['لوله‌کشی','Plomberie','Fontanería'],HVAC:['تهویه مطبوع','Chauffage et climatisation','Climatización'],'Full Wrap':['رپ کامل','Habillage complet','Rotulación completa'],'Partial Wrap':['رپ جزئی','Habillage partiel','Rotulación parcial'],Decal:['برچسب','Autocollants','Vinilos'],'Channel Wrap':['رپ کانالی','Habillage de bandes','Rotulación de franjas'],'Full wrap':['رپ کامل','Habillage complet','Rotulación completa'],'Partial wrap':['رپ جزئی','Habillage partiel','Rotulación parcial'],'Commercial / fleet':['تبلیغاتی / ناوگان','Commercial / flotte','Comercial / flota'],'Lettering & decals':['نوشته و برچسب','Lettrage et autocollants','Rótulos y vinilos'],'Paint protection film':['فیلم محافظ رنگ (PPF)','Film de protection (PPF)','Película de protección (PPF)'],'Window tint':['دودی شیشه','Teinte de vitres','Polarizado'],Wallpaper:['کاغذ دیواری','Papier peint','Papel tapiz'],'Window graphics':['گرافیک شیشه','Graphiques de vitrine','Gráficos para ventanas'],Print:['چاپ','Impression','Impresión'],Apparel:['پوشاک','Vêtements','Ropa'],Signage:['تابلو','Enseignes','Rótulos'],Car:['سواری','Voiture','Auto'],Bus:['اتوبوس','Autobus','Autobús'],Boat:['قایق','Bateau','Barco'],Motorcycle:['موتورسیکلت','Moto','Moto'],'Building / storefront':['ساختمان / ویترین','Bâtiment / vitrine','Edificio / escaparate'],Gloss:['براق','Brillant','Brillante'],Matte:['مات','Mat','Mate'],Satin:['ساتن','Satiné','Satinado'],Metallic:['متالیک','Métallisé','Metalizado'],Chrome:['کروم','Chrome','Cromo'],'Colour shift':['تغییر رنگ نوری','Caméléon','Tornasol'],'Carbon fibre':['فیبر کربن','Fibre de carbone','Fibra de carbono'],'Printed graphics':['گرافیک چاپی','Graphiques imprimés','Gráficos impresos'],'Clear / PPF':['شفاف / PPF','Transparent / PPF','Transparente / PPF']};
/* Our Work taxonomy (same ids as Admin → Our Work, hp/php/satin-new/portfolio.php) */
const SERVICES={'full-wrap':'Full wrap','partial-wrap':'Partial wrap','colour-change':'Colour change','commercial':'Commercial / fleet','lettering':'Lettering & decals','ppf':'Paint protection film','window-tint':'Window tint','wallpaper':'Wallpaper','window-graphics':'Window graphics','print':'Print','apparel':'Apparel','signage':'Signage'};
const FINISHES={gloss:'Gloss',matte:'Matte',satin:'Satin',metallic:'Metallic',chrome:'Chrome','colour-shift':'Colour shift',carbon:'Carbon fibre',printed:'Printed graphics',clear:'Clear / PPF'};
const kindLabel=(p,w,lang)=>p.services?.[0]&&p.custom?label(SERVICES[p.services[0]]||p.services[0],lang):p.category==='commercial'?w.commercial:p.category==='colour'?w.colour:label(SERVICES[p.services?.[0]]||'Other',lang);
const searchText=p=>[p.title,...(p.tags||[]),p.model,p.make,p.year,p.client,p.vehicle,p.industry,p.description,...(p.services||[]).map(s=>SERVICES[s]),...(p.finishes||[]).map(f=>FINISHES[f])].filter(Boolean).join(' ').toLowerCase();
const label=(s,lang)=>lang==='en'?s:vocab[s]?.[['fa','fr','es'].indexOf(lang)]||s;
const base=lang=>'/satin'+(lang==='en'?'':'/'+lang);
const origin=(typeof location!=='undefined'&&/^https?:$/.test(location.protocol)&&location.origin)||'https://satin-graphic-website.mehrad-tr.chatgpt.site';
const image=p=>p.cover||p.images[0];
/* ---- project page copy: H1 subtitle, extra detail rows and an "About this project" section built only from the
   project's own fields and facts the site states elsewhere (films, process, warranty) ---- */
const L4=lang=>['en','fa','fr','es'].indexOf(lang)<0?0:['en','fa','fr','es'].indexOf(lang);
const VEH={Van:['van','ون','fourgon','furgoneta'],'Mini Van':['minivan','مینی‌ون','minifourgonnette','minivan'],Truck:['truck','کامیون','camion','camión'],Trailer:['trailer','تریلر','remorque','remolque'],SUV:['SUV','شاسی‌بلند','VUS','SUV'],Sedan:['car','خودروی سواری','voiture','auto'],Other:['vehicle','خودرو','véhicule','vehículo']};
const COV={'Full Wrap':['full wrap','رپ کامل','habillage complet','rotulación completa'],'Partial Wrap':['partial wrap','رپ جزئی','habillage partiel','rotulación parcial'],Decal:['decals & lettering','برچسب و نوشته','lettrage et autocollants','rótulos y vinilos'],'Channel Wrap':['channel wrap','رپ کانالی','habillage de bandes','rotulación de franjas']};
const SVC_PAGE={Van:['/vehicle-wraps/commercial/vans/',['van wraps','رپ ون','l’habillage de fourgons','la rotulación de furgonetas']],'Mini Van':['/vehicle-wraps/commercial/vans/',['van and minivan wraps','رپ ون و مینی‌ون','l’habillage de fourgons et minifourgonnettes','la rotulación de furgonetas y minivans']],Truck:['/vehicle-wraps/commercial/pickups/',['pickup truck wraps','رپ وانت و کامیون','l’habillage de camionnettes','la rotulación de camionetas']],Trailer:['/vehicle-wraps/commercial/trailers/',['trailer wraps','رپ تریلر','l’habillage de remorques','la rotulación de remolques']]};
const EST={'Mini Van':'minivan',Trailer:'trailer',SUV:'suv',Sedan:'sedan'};
const COLOURS={yellow:['yellow','زرد','jaune','amarillo'],red:['red','قرمز','rouge','rojo'],purple:['purple','بنفش','violet','morado'],green:['green','سبز','vert','verde'],blue:['blue','آبی','bleu','azul']};
const veh=(p,lang)=>(VEH[p.vehicle]||VEH.Other)[L4(lang)];
function colourOf(p){const w=String(p.title).trim().split(/\s+/).pop().toLowerCase();return COLOURS[w]?w:'';}
function makeOf(p){return String(p.model||p.title).trim();}
/* short descriptive line under the project name (keeps H1s unique when several projects share a name) */
function projectSub(p,lang,records){const i=L4(lang);let sub;
if(p.custom)sub=[(p.services||[]).map(x=>label(SERVICES[x]||x,lang)).join(' · '),p.model].filter(Boolean).join(' · ');
else if(p.category==='colour'){const c=colourOf(p);sub=[['Colour change wrap','رپ تغییر رنگ','Changement de couleur','Cambio de color'][i],i&&c&&COLOURS[c][i]].filter(Boolean).join(' · ');}
else{const ind=p.industry&&p.industry!=='Other'?label(p.industry,lang):'',v=p.vehicle&&p.vehicle!=='Other'?veh(p,lang):'',cv=COV[p.coverage]?.[i]||'';
sub=i===0?[ind,v,cv].filter(Boolean).join(' ').replace(/^./,c=>c.toUpperCase())||'Commercial vehicle graphics':[ind,label(p.vehicle&&p.vehicle!=='Other'?p.vehicle:'',lang),cv].filter(Boolean).join(' · ')||label('Commercial wrap',lang);}
const key=x=>String(x.title).trim().toLowerCase(),same=(records||[]).filter(x=>key(x)===key(p)&&x.category===p.category);
const n=same.findIndex(x=>x.id===p.id);if(same.length>1&&n>0)sub+=' · '+(['Project','پروژه','Projet','Proyecto'][i])+' '+(n+1);
return sub;}
function projectRows(p,lang){const i=L4(lang);if(p.custom)return [];
const svc=p.category==='colour'?['Colour change wrap','رپ تغییر رنگ','Changement de couleur','Cambio de color'][i]:['Commercial vehicle graphics','گرافیک تبلیغاتی خودرو','Marquage de véhicule commercial','Rotulación de vehículo comercial'][i];
const mat=p.category==='colour'?['Colour-change cast vinyl film','فیلم وینیل کست تغییر رنگ','Film vinyle coulé de changement de couleur','Vinilo fundido de cambio de color'][i]:p.coverage==='Decal'?['Cut or printed vinyl','وینیل برش‌خورده یا چاپی','Vinyle découpé ou imprimé','Vinilo de corte o impreso'][i]:['Printed cast vinyl + laminate','وینیل کست چاپی + لمینیت','Vinyle coulé imprimé + laminé','Vinilo fundido impreso + laminado'][i];
return [[['Service','خدمت','Service','Servicio'][i],svc],[['Material','متریال','Matériau','Material'][i],mat],[['Installed by','نصب توسط','Posé par','Instalado por'][i],['Satin Auto Wrap, Vaughan, ON','Satin Auto Wrap، وان، انتاریو','Satin Auto Wrap, Vaughan (Ont.)','Satin Auto Wrap, Vaughan, ON'][i]]];}
const COV_EN={'Full Wrap':'a full wrap','Partial Wrap':'a partial wrap',Decal:'decals and lettering','Channel Wrap':'a channel wrap'},IND_EN={Construction:'a construction company',Plumbing:'a plumbing company',HVAC:'an HVAC contractor',Electric:'an electrical contractor','Wood and Kitchen':'a kitchen and millwork business',Trading:'a trading company'},an=v=>/^(SUV|[aeiou])/i.test(v)?'an':'a';
const A_=(href,text)=>`<a href="${href}">${text}</a>`;
function industryLine(p,v){return ({Construction:`Construction companies spend the day on job sites and residential streets, so a branded ${v} keeps working in front of homeowners and general contractors long after the crew has left.`,Plumbing:`For a plumbing company the ${v} is often the first thing a customer sees in the driveway: clear branding tells them the right people have arrived and reminds the neighbours who to call.`,HVAC:`Heating and cooling contractors drive between service calls all day, so a clearly branded ${v} turns every trip and every driveway into advertising for the business.`,Electric:`Electrical contractors are judged on professionalism, and a sharp, readable ${v} with the company name, services and phone number shows customers they have hired an established business.`,'Wood and Kitchen':`Kitchen, cabinet and millwork businesses sell a finished look, so their vehicles should look finished too: the ${v} carries the brand to every delivery and installation.`,Trading:`For trading and distribution businesses the ${v} is on the road across the GTA every day, which makes it one of the most cost-effective advertising spaces the company owns.`})[p.industry]||`A branded ${v} works as advertising every time it is driven or parked, across Vaughan, Toronto and the rest of the GTA.`;}
function coverageLine(p,v){return ({'Full Wrap':`A full wrap covers the painted body of the ${v} with printed graphics, so every side works as advertising. We print full wraps on 3M IJ180mC-10 cast vinyl under a matching gloss, satin or matte laminate; the cast film conforms to curves and recesses and protects the factory paint underneath.`,'Partial Wrap':`A partial wrap covers selected areas of the ${v} — usually the sides and rear — and uses the factory paint colour as part of the design. It costs less than a full wrap but still reads as a fully branded vehicle, and it is printed on the same 3M cast vinyl and laminate as our full wraps.`,Decal:`Decals and lettering put the essentials — company name, logo, phone number and website — on the ${v} in cut or printed vinyl. It is the most affordable way to brand a work vehicle (lettering is typically about 22% of the price of a full wrap) and it is easy to update when your details change.`,'Channel Wrap':`A channel wrap applies printed graphics to selected sections of the ${v} instead of the whole body, combining the vehicle’s own colour with a strong band of branding. It gives far more impact than lettering alone while keeping the cost below a full wrap.`})[p.coverage]||`Commercial graphics turn the ${v} into advertising that works every time it is on the road.`;}
function projectAbout(p,lang){if(p.custom)return '';const i=L4(lang),b=base(lang),title=esc(String(p.title).trim()),h=['About this project','درباره این پروژه','À propos de ce projet','Sobre este proyecto'][i];let body;
if(p.category==='colour'){const make=esc(makeOf(p)),c=colourOf(p),cn=c?COLOURS[c][i]:'';
body=[[`${title} is a colour-change project: ${c?`the ${make} was wrapped in ${cn}`:`the visible colour of this ${make} was changed`} with cast vinyl film instead of paint. The factory paint stays underneath, protected from stone chips and UV, and the film can be removed later if you want the original colour back.`,
`We work with colour-change films from 3M, Avery Dennison and other leading brands in gloss, satin, matte, metallic and colour-shift finishes. The car is washed and decontaminated first, and handles, lights and trim are removed where needed so the film tucks behind the edges instead of being cut on the panel. The wrap is applied panel by panel in our climate-controlled bay in Vaughan and is backed by our 5-year workmanship warranty against lifting and peeling.`,
`Thinking about a new colour? Try films on your type of vehicle in the ${A_(b+'/vehicle-wraps/visualizer/','car wrap visualizer')}, compare finishes on our ${A_(b+'/vehicle-wraps/color-change/','colour change wraps')} page, read ${A_('/satin/guides/wrap-lifespan-canadian-winter/','how long a wrap lasts in a Canadian winter')} or see ${A_('/satin/vehicle-wraps/vaughan/','vehicle wraps in Vaughan')}.`],
[`${title} یک پروژه تغییر رنگ است: رنگ ظاهری ${make}${cn?` با فیلم ${cn}`:''} بدون رنگ‌آمیزی و با فیلم وینیل کست تغییر کرده است. رنگ کارخانه زیر فیلم باقی می‌ماند و از سنگ‌ریزه و اشعه UV محافظت می‌شود و فیلم را می‌توان بعداً برداشت.`,
`ما با فیلم‌های تغییر رنگ 3M، Avery Dennison و برندهای معتبر دیگر در فینیش‌های براق، ساتن، مات، متالیک و تغییر رنگ نوری کار می‌کنیم. خودرو ابتدا شسته و آلودگی‌زدایی می‌شود و در صورت نیاز دستگیره‌ها، چراغ‌ها و تزئینات باز می‌شوند تا فیلم پشت لبه‌ها برود. نصب قطعه به قطعه در سالن کنترل‌شده ما در وان انجام می‌شود و ۵ سال ضمانت اجرا دارد.`,
`رنگ‌ها را روی خودروی خود در ${A_(b+'/vehicle-wraps/visualizer/','نمایشگر رنگ رپ')} امتحان کنید یا صفحه ${A_(b+'/vehicle-wraps/color-change/','رپ تغییر رنگ')} را ببینید.`],
[`${title} est un projet de changement de couleur : ${c?`la ${make} a été habillée en ${cn}`:`la couleur visible de ce véhicule ${make} a été changée`} avec un film vinyle coulé plutôt qu’avec de la peinture. La peinture d’origine reste dessous, protégée des éclats et des UV, et le film peut être retiré plus tard.`,
`Nous utilisons des films de changement de couleur 3M, Avery Dennison et d’autres grandes marques en finis brillant, satiné, mat, métallisé et caméléon. Le véhicule est lavé et décontaminé, puis poignées, feux et garnitures sont démontés au besoin pour que le film passe derrière les bords. La pose se fait panneau par panneau dans notre atelier climatisé de Vaughan, avec une garantie de main-d’œuvre de 5 ans.`,
`Essayez des couleurs sur votre type de véhicule avec le ${A_(b+'/vehicle-wraps/visualizer/','visualiseur d’habillage')} ou consultez la page ${A_(b+'/vehicle-wraps/color-change/','changement de couleur')}.`],
[`${title} es un proyecto de cambio de color: ${c?`el ${make} se rotuló en ${cn}`:`el color visible de este ${make} se cambió`} con vinilo fundido en lugar de pintura. La pintura de fábrica queda debajo, protegida de piedras y rayos UV, y el vinilo se puede retirar más adelante.`,
`Trabajamos con vinilos de cambio de color de 3M, Avery Dennison y otras marcas líderes en acabados brillante, satinado, mate, metalizado y tornasol. El auto se lava y descontamina, y se desmontan manijas, luces y molduras cuando hace falta para que el vinilo pase detrás de los bordes. La instalación se hace panel por panel en nuestro taller climatizado de Vaughan, con 5 años de garantía de mano de obra.`,
`Pruebe colores en su tipo de vehículo con el ${A_(b+'/vehicle-wraps/visualizer/','visualizador de rotulación')} o vea la página de ${A_(b+'/vehicle-wraps/color-change/','cambio de color')}.`]][i];}
else{const v=veh(p,lang),svc=SVC_PAGE[p.vehicle],est=EST[p.vehicle]?b+'/vehicle-wraps/estimator/'+EST[p.vehicle]+'/':b+'/vehicle-wraps/estimator/';
body=[[`${title} is a commercial vehicle graphics project${COV_EN[p.coverage]?`: ${COV_EN[p.coverage]} on ${an(v)} ${v}`:''}${IND_EN[p.industry]?` for ${IND_EN[p.industry]}`:''}. ${coverageLine(p,v)}`,
`${industryLine(p,v)} Commercial projects like this one follow the same steps at our shop: we map door handles, seams and body lines on a template of the ${v} so text never lands on a gap, send a proof for approval, print and laminate in-house, then install panel by panel in our climate-controlled bay at 50 Viceroy Rd in Vaughan. Installs are backed by our 5-year workmanship warranty against lifting and peeling.`,
`Planning something similar? See ${svc?A_(b+svc[0],svc[1][0]):A_(b+'/vehicle-wraps/commercial/','commercial vehicle wraps')}${p.vehicle==='Truck'?`, ${A_(b+'/vehicle-wraps/commercial/box-trucks/','box truck wraps')}`:''}${svc?` and ${A_(b+'/vehicle-wraps/commercial/','commercial vehicle wraps')}`:''}, get a price range with the ${A_(est,'wrap cost estimator')}${p.coverage==='Decal'?`, read about ${A_('/satin/vehicle-wraps/lettering/','vehicle lettering and decals')}`:''} or learn more about ${A_('/satin/vehicle-wraps/vaughan/','vehicle wraps in Vaughan')}.`],
[`${title} یک پروژه گرافیک تبلیغاتی خودرو است${p.coverage?` (${COV[p.coverage]?.[1]||''} روی ${v})`:''}${p.industry&&p.industry!=='Other'?` برای کسب‌وکاری در حوزه ${esc(label(p.industry,lang))}`:''}. طرح روی قالب دقیق خودرو چیده می‌شود تا دستگیره‌ها، درزها و خطوط بدنه روی متن نیفتند؛ پس از تأیید پیش‌نمایش، چاپ و لمینیت در کارگاه خودمان انجام می‌شود.`,
`نصب قطعه به قطعه در سالن کنترل‌شده ما در 50 Viceroy Rd، وان انجام می‌شود و ۵ سال ضمانت اجرا در برابر بلند شدن و پوسته شدن دارد. فول‌رپ‌ها روی وینیل کست 3M IJ180mC-10 با لمینیت براق، ساتن یا مات چاپ می‌شوند.`,
`برای پروژه مشابه ${svc?A_(b+svc[0],svc[1][1]):A_(b+'/vehicle-wraps/commercial/','رپ تبلیغاتی خودرو')} را ببینید یا با ${A_(est,'برآوردگر هزینه رپ')} قیمت تقریبی بگیرید.`],
[`${title} est un projet de marquage de véhicule commercial${p.coverage?` (${COV[p.coverage]?.[2]||''})`:''}${p.industry&&p.industry!=='Other'?` pour une entreprise du secteur ${esc(label(p.industry,lang).toLowerCase())}`:''}. La mise en page est préparée sur un gabarit du véhicule pour que poignées, joints et lignes de carrosserie ne coupent jamais le texte, puis une épreuve est envoyée pour approbation avant l’impression et le laminage en atelier.`,
`La pose se fait panneau par panneau dans notre atelier climatisé du 50 Viceroy Rd à Vaughan, avec une garantie de main-d’œuvre de 5 ans contre le soulèvement et le décollement. Les habillages complets sont imprimés sur vinyle coulé 3M IJ180mC-10 sous un laminé brillant, satiné ou mat.`,
`Un projet semblable ? Voyez ${svc?A_(b+svc[0],svc[1][2]):A_(b+'/vehicle-wraps/commercial/','le marquage de véhicules commerciaux')} ou obtenez une fourchette de prix avec l’${A_(est,'estimateur de coût')}.`],
[`${title} es un proyecto de rotulación de vehículo comercial${p.coverage?` (${COV[p.coverage]?.[3]||''})`:''}${p.industry&&p.industry!=='Other'?` para una empresa del sector ${esc(label(p.industry,lang).toLowerCase())}`:''}. El diseño se prepara sobre una plantilla del vehículo para que manijas, juntas y líneas de la carrocería nunca corten el texto, y se envía una prueba para aprobación antes de imprimir y laminar en el taller.`,
`La instalación se hace panel por panel en nuestro taller climatizado de 50 Viceroy Rd en Vaughan, con 5 años de garantía de mano de obra contra levantamiento y desprendimiento. Las rotulaciones completas se imprimen en vinilo fundido 3M IJ180mC-10 con laminado brillante, satinado o mate.`,
`¿Un proyecto similar? Vea ${svc?A_(b+svc[0],svc[1][3]):A_(b+'/vehicle-wraps/commercial/','la rotulación comercial')} u obtenga un rango de precio con el ${A_(est,'estimador de costos')}.`]][i];}
return `<section class="portfolio-project-about"><div class="wrap"><h2>${h}</h2><div class="portfolio-about-copy">${body.map(t=>`<p>${t}</p>`).join('')}</div></div></section>`;}
function card(p,lang){const w=words[lang];return `<a class="portfolio-card" href="${base(lang)}/portfolio/projects/${p.slug}/"><div class="portfolio-card-photo"><img src="${image(p).thumb||image(p).src}" alt="${esc(image(p).alt)}" width="640" height="450" loading="lazy"><span>${p.images.length} ${w.photos}</span></div><div class="portfolio-card-info"><small>${p.featured?'★ ':''}${kindLabel(p,w,lang)}${p.vehicle?' · '+esc(label(p.vehicle,lang)):''}</small><h2>${esc(p.title)}</h2><div class="portfolio-tags">${p.tags.slice(0,3).map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div><span class="portfolio-view">${w.view} ↗</span></div></a>`;}
export function portfolioPage(lang='en',path='/portfolio',query=new URLSearchParams(),records=projects){
const projects=records;lastRecords=records;const w=words[lang]||words.en,slug=path.split('/projects/')[1],p=slug?projects.find(p=>p.slug===slug):null,b=base(lang);if(slug&&!p)return null;
if(p){const category=kindLabel(p,w,lang);const html=`<section class="portfolio-project-hero"><div class="wrap"><nav class="portfolio-crumbs" aria-label="Breadcrumb"><a href="${b}/">Satin Graphic</a><span>/</span><a href="${b}/portfolio/">${w.portfolio}</a><span>/</span><span>${esc(p.title)}</span></nav><div class="portfolio-project-top"><div><span class="eyebrow">${category}</span><h1>${esc(String(p.title).trim())}<span class="portfolio-h1-sub">${esc(projectSub(p,lang,projects))}</span></h1><p>${description(p,lang)}</p><div class="portfolio-tags">${p.tags.map(t=>`<span>${esc(label(t,lang))}</span>`).join('')}</div></div><a class="btn" href="${b}/contact/">${w.quote}</a></div><figure><img src="${image(p).src}" alt="${esc(image(p).alt)}" width="${image(p).width}" height="${image(p).height}" fetchpriority="high"><figcaption>${esc(p.title)} · ${category}</figcaption></figure></div></section><section class="portfolio-project-details"><div class="wrap"><h2>${w.details}</h2><dl>${[[w.vehicle,p.custom?[label(p.vehicle,lang),p.model].filter(Boolean).join(' · '):label(p.vehicle||p.model,lang)],[w.services,(p.services||[]).map(s=>label(SERVICES[s]||s,lang)).join(', ')],[w.finish,(p.finishes||[]).map(f=>label(FINISHES[f]||f,lang)).join(', ')],[w.industry,label(p.industry,lang)],[w.coverage,p.custom?'':label(p.coverage,lang)],[w.client,p.client],...projectRows(p,lang)].filter(a=>a[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div><dt>${w.photos}</dt><dd>${p.images.length}</dd></div></dl><div class="portfolio-project-photos">${p.images.map((im,i)=>`<figure><a href="${im.src}" target="_blank" rel="noopener"><img src="${im.src}" alt="${esc(im.alt)}" width="${im.width}" height="${im.height}" loading="lazy"></a><figcaption>${w.photo} ${i+1} · ${esc(p.title)}</figcaption></figure>`).join('')}</div><a href="${b}/portfolio/" class="btn ghost">${w.back}</a></div></section>${projectAbout(p,lang)}<section class="portfolio-related"><div class="wrap"><h2>${w.related}</h2><div class="portfolio-grid">${[...projects.filter(x=>x.id!==p.id&&x.category===p.category&&(x.vehicle===p.vehicle||x.model===p.model)),...projects.filter(x=>x.id!==p.id&&(x.services||[]).some(s=>(p.services||[]).includes(s))&&!(x.category===p.category&&(x.vehicle===p.vehicle||x.model===p.model))),...projects.filter(x=>x.id!==p.id&&x.category===p.category)].filter((x,i,a)=>a.indexOf(x)===i).slice(0,3).map(x=>card(x,lang)).join('')}</div></div></section>`;return {title:p.title,html,portfolio:true,meta:{title:String(p.title).trim()+' · '+projectSub(p,lang,projects)+' | Satin Graphic',description:description(p,lang),image:image(p).src},record:p};}
const category=path==='/portfolio/commercial'?'commercial':path==='/portfolio/colour-change'?'colour':'',q=(query.get('q')||'').trim().toLowerCase(),vehicle=query.get('vehicle')||'',industry=query.get('industry')||'',coverage=query.get('coverage')||'',service=query.get('service')||'',finish=query.get('finish')||'';
const matches=projects.filter(p=>(!category||p.category===category)&&(!vehicle||p.vehicle===vehicle)&&(!industry||p.industry===industry)&&(!coverage||p.coverage===coverage)&&(!service||(p.services||[]).includes(service))&&(!finish||(p.finishes||[]).includes(finish))&&(!q||q.split(/\s+/).every(t=>searchText(p).includes(t))));const totalPages=Math.max(1,Math.ceil(matches.length/24)),number=Math.min(totalPages,Math.max(1,parseInt(query.get('page'))||1)),slice=matches.slice((number-1)*24,number*24),title=category==='commercial'?w.commercialH1:category==='colour'?w.colourH1:w.portfolio;
const options=(key,title)=>`<label>${title}<select name="${key}"><option value="">${w.any}</option>${[...new Set(projects.map(p=>p[key]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${v===query.get(key)?'selected':''}>${esc(label(v,lang))}</option>`).join('')}</select></label>`;
const inCat=projects.filter(p=>!category||p.category===category),serviceCount=Object.keys(SERVICES).map(k=>[k,inCat.filter(p=>(p.services||[]).includes(k)).length]).filter(a=>a[1]),usedFinishes=Object.keys(FINISHES).filter(k=>projects.some(p=>(p.finishes||[]).includes(k)));
const chipHref=k=>{const qs=new URLSearchParams(query);qs.delete('page');if(k)qs.set('service',k);else qs.delete('service');const t=qs.toString();return b+path+'/'+(t?'?'+t:'');};
const pageHref=n=>{const qs=new URLSearchParams(query);qs.set('page',n);return b+path+'/?'+qs.toString();};
const html=`<section class="portfolio-intro"><div class="wrap"><span class="eyebrow">Satin Auto Wrap × Satin Graphic</span><div class="portfolio-intro-top"><h1>${title}</h1><p>${w.intro}</p></div><nav class="portfolio-categories" aria-label="${w.portfolio}">${[['',w.all],['/commercial',w.commercial],['/colour-change',w.colour]].map(([s,t])=>`<a ${path==='/portfolio'+s?'aria-current="page"':''} href="${b}/portfolio${s}/">${t}<small>${projects.filter(p=>!s||p.category===(s==='/commercial'?'commercial':'colour')).length}</small></a>`).join('')}</nav></div></section><section class="portfolio-results"><div class="wrap"><form class="portfolio-filters" data-portfolio-filter action="${b+path}/" method="get"><label class="portfolio-search">${w.search}<input type="search" name="q" value="${esc(query.get('q')||'')}" placeholder="${w.search}"></label>${options('vehicle',w.vehicle)}${options('industry',w.industry)}${options('coverage',w.coverage)}${usedFinishes.length?`<label>${w.finish}<select name="finish"><option value="">${w.any}</option>${usedFinishes.map(k=>`<option value="${k}" ${k===finish?'selected':''}>${esc(label(FINISHES[k],lang))}</option>`).join('')}</select></label>`:''}${service?`<input type="hidden" name="service" value="${esc(service)}">`:''}<button class="btn sm" type="submit">${w.search}</button><a href="${b+path}/">${w.clear}</a></form>${serviceCount.length>1?`<nav class="portfolio-chips" aria-label="${w.services}"><a href="${chipHref('')}" ${!service?'aria-current="true"':''}>${w.allServices}</a>${serviceCount.map(([k,n])=>`<a href="${chipHref(k)}" ${k===service?'aria-current="true"':''}>${esc(label(SERVICES[k],lang))}<small>${n}</small></a>`).join('')}</nav>`:''}<div class="portfolio-count"><span>${matches.length} ${w.results}</span><span>${number} / ${totalPages}</span></div><div class="portfolio-grid">${slice.map(p=>card(p,lang)).join('')}</div>${!matches.length?`<p class="portfolio-no-results">${w.empty}</p>`:''}<nav class="portfolio-pagination" aria-label="Pagination">${number>1?`<a class="btn ghost" href="${pageHref(number-1)}">${w.prev}</a>`:''}${Array.from({length:totalPages},(_,i)=>i+1).filter(n=>n===1||n===totalPages||Math.abs(n-number)<=2).map(n=>`<a href="${pageHref(n)}" ${n===number?'aria-current="page"':''}>${n}</a>`).join('')}${number<totalPages?`<a class="btn ghost" href="${pageHref(number+1)}">${w.next}</a>`:''}</nav></div></section>`;
return {title,html,portfolio:true,meta:{title:title+' · Vehicle wrap portfolio | Satin Graphic',description:w.intro,image:image(slice[0]||projects[0]).src,noindex:!!(q||vehicle||industry||coverage||service||finish)},listing:slice,page:number};
}
function description(p,lang){if(p.description)return esc(p.description);const specs=[p.vehicle||p.model,p.coverage,p.industry].filter(Boolean).map(s=>label(s,lang)).join(' · ');return ({en:`${p.title} — ${p.category==='commercial'?'commercial vehicle graphics':'colour-change wrap'} by Satin Auto Wrap. ${specs}. Explore the finished project and its photos.`,fa:`${p.title} — ${p.category==='commercial'?'رپ تبلیغاتی خودرو':'رپ تغییر رنگ'} توسط Satin Auto Wrap. ${specs}. تصاویر کامل پروژه را ببینید.`,fr:`${p.title} — ${p.category==='commercial'?'marquage de véhicule commercial':'changement de couleur'} par Satin Auto Wrap. ${specs}. Découvrez les photos du projet terminé.`,es:`${p.title} — ${p.category==='commercial'?'rotulación de vehículo comercial':'cambio de color'} de Satin Auto Wrap. ${specs}. Descubre las fotos del proyecto terminado.`})[lang];}
export function portfolioSEO(lang,path,page,query=new URLSearchParams()){
const canonical=origin+base(lang)+path+'/' +(page.page>1&&!page.meta.noindex?'?page='+page.page:''),im=origin+page.meta.image;const graph=[{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Satin Graphic',item:origin+base(lang)+'/'},{'@type':'ListItem',position:2,name:words[lang].portfolio,item:origin+base(lang)+'/portfolio/'},...(page.record?[{'@type':'ListItem',position:3,name:page.record.title,item:canonical}]:[])]}];if(page.record){const p=page.record;graph.push({'@type':'CreativeWork',name:p.title,description:page.meta.description,url:canonical,creator:{'@type':'Organization',name:'Satin Auto Wrap'},keywords:p.tags.join(', '),image:p.images.map(i=>({'@type':'ImageObject',contentUrl:origin+i.src,caption:i.alt,width:i.width,height:i.height}))});}else graph.push({'@type':'CollectionPage',name:page.title,url:canonical,description:page.meta.description,mainEntity:{'@type':'ItemList',itemListElement:page.listing.map((p,i)=>({'@type':'ListItem',position:(page.page-1)*24+i+1,name:p.title,url:origin+base(lang)+'/portfolio/projects/'+p.slug+'/'}))}});return {...page.meta,canonical,image:im,jsonld:{'@context':'https://schema.org','@graph':graph}};}
let lastRecords=null;
function addToIndex(records){const sec=document.querySelector('[data-cms-section="sprojects"]');if(!sec)return;const known=new Set([...sec.querySelectorAll('a[href]')].map(a=>a.getAttribute('href')));const extra=records.filter(p=>p.custom&&!known.has('/satin/portfolio/projects/'+p.slug+'/'));if(!extra.length)return;const ul=sec.querySelector('.proj-index');if(!ul)return;for(const p of extra){const li=document.createElement('li');const a=document.createElement('a');a.href='/satin/portfolio/projects/'+p.slug+'/';a.textContent=p.title;li.append(a);ul.prepend(li);}}
export function mountPortfolio(root,navigate){try{if(lastRecords)addToIndex(lastRecords);}catch{}const form=root.querySelector('[data-portfolio-filter]');if(form){form.addEventListener('submit',e=>{e.preventDefault();const url=new URL(form.action,location.origin);for(const [k,v]of new FormData(form))if(v)url.searchParams.set(k,v);navigate(url);});form.querySelectorAll('select').forEach(s=>s.addEventListener('change',()=>form.requestSubmit()));}}